// Generates every shipped file from tools/data.js + src/ (hand-written Lua, textures).
//   npm run gen               -> write files
//   node tools/gen.js --check -> exit 1 if any generated file is out of date (used by npm test)
// B42 (>= 42.13 registries): 42/media/registries.lua + scripts + common/ JSON translations (UTF-8).
// B41: ProfessionFactory/TraitFactory Lua + <Type>_<LANG>.txt translations (EN UTF-8, PTBR Cp1252/latin1).
const fs = require('fs');
const path = require('path');
const D = require('./data');

const ROOT = path.join(__dirname, '..');
const MOD = path.join(ROOT, 'Contents', 'mods', 'KRjobs');
const B42 = path.join(MOD, '42', 'media');
const B41 = path.join(MOD, 'media');
const COMMON_TR = path.join(MOD, 'common', 'media', 'lua', 'shared', 'Translate');
const SRC = path.join(ROOT, 'src');
const CHECK = process.argv.includes('--check');
const outputs = [];
const put = (p, data) => outputs.push([p, Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf8')]);
const lstr = (s) => JSON.stringify(s);
const HDR = '-- GENERATED by tools/gen.js from tools/data.js. Do not edit by hand.\n';
const NS = 'krjobs';

const traitById = Object.fromEntries(D.TRAITS.map((t) => [t.id, t]));
const profs41 = D.PROFESSIONS.filter((p) => !p.b42only);
const traits41 = D.TRAITS.filter((t) => profs41.some((p) => p.traits.includes(t.id)));

// ---------- keys / per-build views (exported for tests) ----------
const K = {
  prof: (p) => `UI_prof_KRjobs_${p.id}`,
  profDesc: (p) => `UI_profdesc_KRjobs_${p.id}`,
  trait: (t) => `UI_trait_KRjobs_${t.id}`,
  traitDesc: (t) => `UI_trait_KRjobs_${t.id}Desc`,
};
function view(build) {
  const b41 = build === '41';
  const profs = (b41 ? profs41 : D.PROFESSIONS).map((p) => ({
    id: p.id, type: b41 ? p.b41 : `${NS}:${p.id}`, icon: b41 ? p.icon41 : p.icon42,
    cost: b41 && p.cost41 !== undefined ? p.cost41 : p.cost,
    xp: b41 && p.xp41 ? p.xp41 : p.xp,
    traits: p.traits.map((t) => (b41 ? traitById[t].b41 : `${NS}:${t}`)),
    vtraits: (b41 ? p.vtraits41 : p.vtraits42) || [],
    ownTraits: p.traits, name: K.prof(p), desc: K.profDesc(p),
  }));
  const traits = (b41 ? traits41 : D.TRAITS).map((t) => ({
    id: t.id, type: b41 ? t.b41 : `${NS}:${t.id}`,
    xp: b41 && t.xp41 ? t.xp41 : t.xp,
    recipes: b41 ? t.recipes41 : t.recipes42,
    kit: b41 && t.kit41 ? t.kit41 : t.kit,
    name: K.trait(t), desc: K.traitDesc(t),
  }));
  return { profs, traits };
}
const xpStr = (xp) => Object.entries(xp).map(([k, v]) => `${k}=${v}`).join(';');

// ---------- B42 registries + scripts ----------
{
  const v = view('42');
  put(path.join(B42, 'registries.lua'), HDR + '-- B42.13+ registries: every custom trait/profession id must be registered before scripts load.\n' +
    v.traits.map((t) => `CharacterTrait.register(${lstr(t.type)})`).join('\n') + '\n' +
    v.profs.map((p) => `CharacterProfession.register(${lstr(p.type)})`).join('\n') + '\n');
  const sh = '// GENERATED by tools/gen.js from tools/data.js. Do not edit by hand.\n';
  const tr = v.traits.map((t) => {
    const lines = ['IsProfessionTrait = true', 'DisabledInMultiplayer = false', `CharacterTrait = ${t.type}`, 'Cost = 0',
      `UIName = ${t.name}`, `UIDescription = ${t.desc}`];
    if (Object.keys(t.xp).length) lines.push(`XPBoosts = ${xpStr(t.xp)}`);
    if (t.recipes.length) lines.push(`GrantedRecipes = ${t.recipes.join(';')}`);
    return `    character_trait_definition ${t.type}\n    {\n${lines.map((l) => `        ${l},`).join('\n')}\n    }\n`;
  }).join('\n');
  put(path.join(B42, 'scripts', 'KRjobs_traits.txt'), sh + 'module Base\n{\n' + tr + '}\n');
  const pr = v.profs.map((p) => {
    const lines = [`CharacterProfession = ${p.type}`, `Cost = ${p.cost}`, `UIName = ${p.name}`, `UIDescription = ${p.desc}`,
      `IconPathName = ${p.icon}`, `GrantedTraits = ${p.traits.concat(p.vtraits).join(';')}`, `XPBoosts = ${xpStr(p.xp)}`];
    return `    character_profession_definition ${p.type}\n    {\n${lines.map((l) => `        ${l},`).join('\n')}\n    }\n`;
  }).join('\n');
  put(path.join(B42, 'scripts', 'KRjobs_professions.txt'), sh + 'module Base\n{\n' + pr + '}\n');
}

// ---------- Kits.lua (per build) ----------
function kits(build) {
  const v = view(build);
  return HDR + '-- Starting kits: { trait = <trait id for this build>, items = { <full item types> } }\nreturn {\n' +
    v.traits.filter((t) => t.kit.length).map((t) => `    { trait = ${lstr(t.type)}, items = { ${t.kit.map(lstr).join(', ')} } },`).join('\n') + '\n}\n';
}
put(path.join(B42, 'lua', 'shared', 'KRjobs', 'Kits.lua'), kits('42'));
put(path.join(B41, 'lua', 'shared', 'KRjobs', 'Kits.lua'), kits('41'));

// ---------- hand-written Lua + textures mirrored into both builds ----------
for (const rel of ['KRjobs/Core.lua', 'KRjobs_Main.lua']) {
  const src = fs.readFileSync(path.join(SRC, 'lua', rel));
  put(path.join(B42, 'lua', 'shared', rel), src);
  put(path.join(B41, 'lua', 'shared', rel), src);
}
for (const f of fs.readdirSync(path.join(SRC, 'textures'))) {
  const src = fs.readFileSync(path.join(SRC, 'textures', f));
  put(path.join(B42, 'textures', f), src);
  put(path.join(B41, 'textures', f), src);
}

// ---------- B41 ProfessionFactory / TraitFactory ----------
{
  const v = view('41');
  const xpList = (xp) => '{ ' + Object.entries(xp).map(([k, n]) => `{ ${lstr(k)}, ${n} }`).join(', ') + ' }';
  const body = HDR +
`-- Build 41 professions. Idempotent: safe to run on every OnGameBoot / OnCreateLivingCharacter (fixes the v1
-- duplicate-profession bug) and skips unknown perks instead of crashing (fixes the v1 Fighter crash on a nil perk).
require "NPCs/MainCreationMethods"

local KRjobsB41 = {}

KRjobsB41.TRAITS = {
${v.traits.map((t) => `    { type = ${lstr(t.type)}, name = ${lstr(t.name)}, desc = ${lstr(t.desc)}, xp = ${xpList(t.xp)}, recipes = { ${t.recipes.map(lstr).join(', ')} } },`).join('\n')}
}

KRjobsB41.PROFESSIONS = {
${v.profs.map((p) => `    { type = ${lstr(p.type)}, name = ${lstr(p.name)}, desc = ${lstr(p.desc)}, icon = ${lstr(p.icon)}, cost = ${p.cost}, xp = ${xpList(p.xp)}, traits = { ${p.traits.concat(p.vtraits).map(lstr).join(', ')} } },`).join('\n')}
}

local function addBoosts(obj, list)
    for _, b in ipairs(list) do
        local perk = Perks[b[1]]
        if perk then obj:addXPBoost(perk, b[2]) end
    end
end

function KRjobsB41.register()
    local addedTrait = false
    for _, t in ipairs(KRjobsB41.TRAITS) do
        if not TraitFactory.getTrait(t.type) then
            local trait = TraitFactory.addTrait(t.type, getText(t.name), 0, getText(t.desc), true)
            addBoosts(trait, t.xp)
            for _, r in ipairs(t.recipes) do trait:getFreeRecipes():add(r) end
            if BaseGameCharacterDetails and BaseGameCharacterDetails.SetTraitDescription then
                BaseGameCharacterDetails.SetTraitDescription(trait)
            end
            addedTrait = true
        end
    end
    if addedTrait and TraitFactory.sortList then TraitFactory.sortList() end
    for _, p in ipairs(KRjobsB41.PROFESSIONS) do
        if not ProfessionFactory.getProfession(p.type) then
            local prof = ProfessionFactory.addProfession(p.type, getText(p.name), p.icon, p.cost, getText(p.desc))
            addBoosts(prof, p.xp)
            for _, tt in ipairs(p.traits) do prof:addFreeTrait(tt) end
            if BaseGameCharacterDetails and BaseGameCharacterDetails.SetProfessionDescription then
                BaseGameCharacterDetails.SetProfessionDescription(prof)
            end
        end
    end
end

Events.OnGameBoot.Add(KRjobsB41.register)
Events.OnCreateLivingCharacter.Add(KRjobsB41.register)

return KRjobsB41
`;
  put(path.join(B41, 'lua', 'shared', 'NPCs', 'KRjobs_Professions.lua'), body);
}

// ---------- translations ----------
function table(lang, build) {
  const L = lang === 'EN' ? 'en' : 'pt';
  const b41 = build === '41';
  const out = {};
  for (const p of b41 ? profs41 : D.PROFESSIONS) { out[K.prof(p)] = p[L].name; out[K.profDesc(p)] = p[L].desc; }
  for (const t of b41 ? traits41 : D.TRAITS) {
    out[K.trait(t)] = t[L].name;
    out[K.traitDesc(t)] = (b41 && t[L + '41'] && t[L + '41'].desc) || t[L].desc;
  }
  return out;
}
for (const lang of ['EN', 'PTBR']) {
  const L = lang === 'EN' ? 'en' : 'pt';
  put(path.join(COMMON_TR, lang, 'UI.json'), JSON.stringify(table(lang, '42'), null, 4) + '\n');
  put(path.join(COMMON_TR, lang, 'Mod.json'), JSON.stringify({ name: D.MOD[L].name, description: D.MOD[L].description }, null, 4) + '\n');
  const t41 = table(lang, '41');
  const txt = `UI_${lang} = {\n` + Object.entries(t41).map(([k, v]) => `    ${k} = ${lstr(v)},`).join('\n') + '\n}\n';
  put(path.join(B41, 'lua', 'shared', 'Translate', lang, `UI_${lang}.txt`), lang === 'EN' ? txt : Buffer.from(txt, 'latin1'));
}

// ---------- write / check ----------
if (require.main === module) {
  let stale = 0;
  for (const [p, data] of outputs) {
    const cur = fs.existsSync(p) ? fs.readFileSync(p) : null;
    if (cur && cur.equals(data)) continue;
    if (CHECK) { stale++; console.log('stale: ' + path.relative(ROOT, p)); continue; }
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, data);
    console.log('wrote ' + path.relative(ROOT, p));
  }
  if (CHECK && stale) process.exit(1);
}

module.exports = { view, K, table, NS };
